// frame: bit 7 fullbright, bits 0-6 frame index. tics: 0xFF = -1.
typedef struct {
    uint8_t sprite;
    uint8_t frame;
    uint8_t tics;
    uint8_t action;
    uint16_t nextstate;
} dmc_state_t;

// dmc_states applies the Freedoom DEHACKED frame changes. Define
// DMC_ORACLE_FRAMES for the upstream frames of the unmodified oracle.
#define DMC_STATE_TICS(st) ((st)->tics == 0xFF ? -1 : (int)(st)->tics)
#define DMC_STATE_FRAME(st) ((((st)->frame & 0x80) << 8) | ((st)->frame & 0x7F))

// radius and height in map units
typedef struct {
    uint16_t flags_lo;
    uint16_t flags_hi;
    uint16_t spawnstate;
    uint16_t spawnhealth;
    uint8_t radius;
    uint8_t height;
} dmc_mobjinfo_t;

#define DMC_MOBJ_FLAGS(mi) ((uint32_t)(mi)->flags_lo | ((uint32_t)(mi)->flags_hi << 16))

// speed in map units per tic (shifted by FRACBITS for MF_MISSILE types)
typedef struct {
    uint16_t seestate;
    uint16_t painstate;
    uint16_t meleestate;
    uint16_t missilestate;
    uint16_t deathstate;
    uint16_t xdeathstate;
    uint16_t painchance;
    uint16_t mass;
    uint8_t speed;
    uint8_t damage;
    uint8_t reactiontime;
    uint8_t seesound;
    uint8_t attacksound;
    uint8_t painsound;
    uint8_t deathsound;
    uint8_t activesound;
} dmc_actorinfo_t;

#define DMC_NONACTOR_REACTIONTIME 8

typedef struct {
    uint8_t ammo;
    uint8_t pad;
    uint16_t upstate;
    uint16_t downstate;
    uint16_t readystate;
    uint16_t atkstate;
    uint16_t flashstate;
} dmc_weaponinfo_t;

// link: sfx number or 0, pitch and volume only for links
typedef struct {
    uint8_t priority;
    uint8_t link;
    uint8_t pitch;
    int8_t volume;
} dmc_sfxinfo_t;

